package com.zabanyar.ai.data.books.story.content.advanced

import com.zabanyar.ai.data.books.story.StoryChapter
import com.zabanyar.ai.data.books.story.StoryContent
import com.zabanyar.ai.data.books.story.StoryParagraph

/**
 * ۲. یادداشت‌های زیرزمینی — فیودور داستایفسکی
 */
object Story2 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_notes_from_underground",
        chapters = listOf(
            chapter1(),
            chapter2(),
            chapter3(),
            chapter4(),
            chapter5(),
            chapter6(),
        )
    )

    // ─────────── فصل ۱: زیرزمین ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Underground", titlePersian = "زیرزمین",
        paragraphs = listOf(
            StoryParagraph("I am a sick man. I am a spiteful man. I am an unattractive man. I believe my liver is diseased.", "من مردی بیمارم. من مردی کینه‌توزم. من مردی زشت و ناخوشایندم. فکر می‌کنم کبدم خراب است."),
            StoryParagraph("But I do not know anything about my disease, and I am not sure what is wrong with me.", "اما هیچ چیز درباره بیماری‌ام نمی‌دانم و مطمئن نیستم چه مشکلی دارم."),
            StoryParagraph("I am not consulting a doctor because I am spiteful, and I will not consult one out of spite.", "به دکتر مراجعه نمی‌کنم چون کینه‌توزم و از روی کینه هم مراجعه نمی‌کنم."),
            StoryParagraph("I know perfectly well that I cannot hurt the doctors by refusing to consult them, and that I am only hurting myself by doing so.", "کاملاً می‌دانم که با امتناع از مراجعه نمی‌توانم به دکترها آسیب بزنم و فقط به خودم آسیب می‌زنم."),
            StoryParagraph("But I will not consult them, out of spite. My liver hurts, so let it hurt even more.", "اما از روی کینه مراجعه نمی‌کنم. کبدم درد می‌کند، پس بگذار بیشتر درد کند."),
            StoryParagraph("I have been living in this way for many years now, in a corner of a cellar, in a state of permanent spite.", "سال‌های بسیاری است که به این شکل زندگی می‌کنم، در گوشه‌ای از یک زیرزمین، در وضعیتی از کینه دائمی."),
            StoryParagraph("I am forty years old, and I have never been able to become anything: neither good nor bad, neither a scoundrel nor an honest man, neither a hero nor an insect.", "چهل ساله‌ام و هرگز نتوانسته‌ام چیزی بشوم: نه خوب و نه بد، نه یاغی و نه مرد شریف، نه قهرمان و نه حشره."),
            StoryParagraph("Now I am living out my life in my corner, taunting myself with the spiteful and useless consolation that an intelligent man cannot become anything seriously.", "حالا زندگی‌ام را در گوشه‌ام می‌گذرانم و خودم را با آن تسلی کینه‌توزانه و بی‌فایده که مرد باهوش نمی‌تواند چیزی به‌طور جدی بشود مسخره می‌کنم."),
            StoryParagraph("Yes, an intelligent man of the nineteenth century must be and is morally obliged to be primarily a characterless being; a man of character, an active man, is primarily a limited being.", "بله، مرد باهوش قرن نوزدهم باید و از نظر اخلاقی موظف است که اساساً موجودی بی‌شخصیت باشد؛ مردی با شخصیت، مردی فعال، اساساً موجودی محدود است."),
            StoryParagraph("That is my conviction after forty years of life. Let me tell you something about myself, about my life, about my ideas, about my failures.", "این باور من پس از چهل سال زندگی است. بگذارید چیزی درباره خودم بگویم، درباره زندگی‌ام، درباره ایده‌هایم، درباره شکست‌هایم."),
            StoryParagraph("I used to be in the civil service, but I am not anymore. I was a spiteful official: I was rude to the petitioners, and I took pleasure in being rude.", "قبلاً در خدمات دولتی بودم اما دیگر نیستم. کارمند کینه‌توزی بودم: با ارباب‌رجوع‌ها بی‌ادب بودم و از بی‌ادبی لذت می‌بردم."),
            StoryParagraph("When someone came to me with a request, I would grind my teeth at them, and I would feel a wave of pleasure when I managed to upset them.", "وقتی کسی با درخواستی به سراغم می‌آمد، دندان‌هایم را به رویش می‌ساییدم و وقتی موفق می‌شدم ناراحتش کنم، موجی از لذت حس می‌کردم."),
            StoryParagraph("I was a petty tyrant, and I knew it, and I enjoyed it, and I hated myself for enjoying it.", "مستبدی کوچک بودم و می‌دانستم و لذت می‌بردم و از اینکه لذت می‌بردم از خودم متنفر بودم."),
            StoryParagraph("There was a reason for this spite, of course; I was deeply conscious of my own insignificance, and I could not bear to be conscious of it.", "البته دلیلی برای این کینه بود؛ عمیقاً از بی‌اهمیتی خودم آگاه بودم و نمی‌توانستم تحمل کنم که از آن آگاه باشم."),
            StoryParagraph("So I tried to compensate by being cruel to others, by humiliating them, by making them feel as small as I felt.", "پس تلاش کردم با ظلم به دیگران جبرانش کنم، با تحقیرشان، با وادار کردنشان به حس کوچکی‌ای که خودم حس می‌کردم."),
            StoryParagraph("And it worked, in its way; for a moment, when I saw the pain in someone's eyes, I felt better about myself.", "و به شیوه خودش کار کرد؛ برای لحظه‌ای، وقتی درد را در چشمان کسی می‌دیدم، درباره خودم بهتر حس می‌کردم."),
            StoryParagraph("But only for a moment; the feeling would always pass, and I would be left with nothing but self-loathing and the same terrible insignificance.", "اما فقط برای لحظه‌ای؛ حس همیشه می‌گذشت و چیزی جز نفرت از خود و همان بی‌اهمیتی هولناک برایم نمی‌ماند."),
            StoryParagraph("I inherited this habit of spite from my childhood; my parents were not kind to me, and I learned early that the world was a place of pain.", "این عادت کینه را از کودکی به ارث بردم؛ والدینم با من مهربان نبودند و زود یاد گرفتم که دنیا جایی پر از درد است."),
            StoryParagraph("My father, a minor official, was cold and distant; my mother, a woman of no particular warmth, died when I was young.", "پدرم، مقامی کوچک، سرد و دور بود؛ مادرم، زنی بدون گرمای خاصی، وقتی جوان بودم مرد."),
            StoryParagraph("I was raised by servants, by distant relatives, by people who did their duty but never offered love.", "توسط خدمتکاران بزرگ شدم، توسط خویشاوندان دور، توسط کسانی که وظیفه‌شان را انجام می‌دادند اما هرگز عشق ارائه نمی‌کردند."),
            StoryParagraph("And so I learned to live without love, without warmth, without any of the things that make life worth living.", "و بنابراین یاد گرفتم بدون عشق زندگی کنم، بدون گرما، بدون هیچ‌کدام از چیزهایی که زندگی را ارزش زیستن می‌بخشند."),
            StoryParagraph("But I also learned to be intelligent, and intelligence became my curse, because it allowed me to see everything and to do nothing.", "اما همچنین یاد گرفتم باهوش باشم و هوش نفرینم شد، چون به من اجازه می‌داد همه چیز را ببینم و هیچ کاری نکنم."),
            StoryParagraph("I could see the stupidity of the people around me, the futility of their ambitions, the meaninglessness of their lives.", "می‌توانستم حماقت اطرافیانم را ببینم، بیهودگی جاه‌طلبی‌هایشان، بی‌معنایی زندگی‌هایشان."),
            StoryParagraph("But I could not do anything about it; I could not change them, could not change myself, could not change anything.", "اما نمی‌توانستم کاری بکنم؛ نمی‌توانستم تغییرشان دهم، خودم را تغییر دهم، هیچ چیز را تغییر دهم."),
            StoryParagraph("And so I retreated into my own mind, into the underground of my own consciousness, where I could at least be free.", "و بنابراین به ذهن خودم عقب‌نشینی کردم، به زیرزمین آگاهی خودم، جایی که حداقل می‌توانستم آزاد باشم."),
            StoryParagraph("The underground is not a place, you understand; it is a state of being, a way of existing, a refusal to participate in the world.", "زیرزمین مکان نیست، می‌فهمید؛ حالتی از بودن است، شیوه‌ای از وجود، امتناع از مشارکت در جهان."),
            StoryParagraph("It is a place where a man can be alone with his thoughts, with his spite, with his self-loathing, without anyone to bother him.", "جایی است که انسان می‌تواند با افکارش تنها باشد، با کینه‌اش، با نفرت از خودش، بدون کسی که مزاحمش شود."),
            StoryParagraph("It is a place where a man can be free, in the only way that matters: free from the world, free from others, free from the burden of having to be something.", "جایی است که انسان می‌تواند آزاد باشد، به تنها شیوه‌ای که اهمیت دارد: آزاد از جهان، آزاد از دیگران، آزاد از بار مجبور بودن به چیزی بودن."),
            StoryParagraph("But this freedom is also a prison, because it cuts you off from everything that makes life worth living.", "اما این آزادی زندانی هم هست، چون تو را از هر چیزی که زندگی را ارزش زیستن می‌بخشد قطع می‌کند."),
            StoryParagraph("And so I am free, and I am miserable, and I am full of spite, and I am alone.", "و بنابراین آزادم و بدبختم و پر از کینه‌ام و تنهایم."),
            StoryParagraph("I could choose to leave the underground; I could choose to participate in the world; I could choose to be something.", "می‌توانستم انتخاب کنم زیرزمین را ترک کنم؛ می‌توانستم انتخاب کنم در جهان مشارکت کنم؛ می‌توانستم انتخاب کنم چیزی باشم."),
            StoryParagraph("But I will not, out of spite. Because the world does not deserve my participation, because other people do not deserve my company, because the universe does not deserve my life.", "اما نمی‌کنم، از روی کینه. چون جهان سزاوار مشارکت من نیست، چون دیگران سزاوار همراهی من نیستند، چون کائنات سزاوار زندگی من نیست."),
            StoryParagraph("This is my rebellion: a rebellion of refusing to participate, of refusing to be anything, of refusing to care.", "این شورش من است: شورشی از امتناع مشارکت، امتناع از چیزی بودن، امتناع از اهمیت دادن."),
            StoryParagraph("It is a small rebellion, and a useless one, and a foolish one, and yet it is mine, and I will cling to it until the end.", "شورشی کوچک است و بی‌فایده و احمقانه و با این حال مال من است و تا آخر به آن چنگ می‌زنم."),
            StoryParagraph("Because it is the only thing I have, the only thing that distinguishes me from the rest of humanity, the only thing that makes me me.", "زیرا تنها چیزی است که دارم، تنها چیزی که مرا از بقیه بشریت متمایز می‌کند، تنها چیزی که مرا من می‌کند."),
            StoryParagraph("Without my spite, I would be nothing; with my spite, I am still nothing, but at least I am a nothing that knows it is nothing.", "بدون کینه‌ام، هیچ می‌بودم؛ با کینه‌ام، هنوز هیچم اما دست‌کم هیچی هستم که می‌داند هیچ است."),
            StoryParagraph("And that, perhaps, is the only wisdom I have to offer: that self-awareness is the only dignity available to a man who has nothing else.", "و این، شاید، تنها خردی است که می‌توانم عرضه کنم: خودآگاهی تنها کرامت موجود برای مردی است که هیچ چیز دیگری ندارد.")
        )
    )

    // ─────────── فصل ۲: رویاهای شبانه ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Daydreams", titlePersian = "رؤیاهای روزانه",
        paragraphs = listOf(
            StoryParagraph("Let me tell you about my dreams, because my dreams were once the only thing that kept me alive.", "بگذارید از رؤیاهایم بگویم، چون رؤیاهایم زمانی تنها چیزی بود که زنده‌ام نگه می‌داشت."),
            StoryParagraph("When I was a young man, before I retreated into the underground, I used to spend hours, days, weeks in a kind of ecstatic dreaming.", "وقتی جوان بودم، پیش از آنکه به زیرزمین عقب‌نشینی کنم، ساعت‌ها، روزها، هفته‌ها را در نوعی رؤیاپردازی سرخوشانه می‌گذراندم."),
            StoryParagraph("I would lie on my sofa, in my tiny room, and I would imagine myself as a great man, a hero, a savior of humanity.", "روی مبل کوچکم دراز می‌کشیدم و خود را مردی بزرگ تصور می‌کردم، قهرمانی، نجات‌دهنده بشریت."),
            StoryParagraph("Sometimes I was a Napoleon, leading armies across Europe; sometimes I was a Byron, a poet of genius; sometimes I was a philanthropist who gave all his wealth to the poor.", "گاهی ناپلئون بودم، ارتش‌ها را در سراسر اروپا رهبری می‌کردم؛ گاهی بایرون بودم، شاعری نابغه؛ گاهی بشردوستی که تمام ثروتش را به فقرا می‌داد."),
            StoryParagraph("In my dreams, I was everything I could never be in reality: brave, generous, wise, loved.", "در رؤیاهایم، هر چیزی بودم که هرگز نمی‌توانستم در واقعیت باشم: شجاع، سخاوتمند، فرزانه، دوست‌داشته."),
            StoryParagraph("The dreams were so vivid, so detailed, so real, that when I woke from them, the reality of my life seemed almost unbearable.", "رؤیاها آنقدر روشن بودند، آنقدر با جزئیات، آنقدر واقعی که وقتی از آنها بیدار می‌شدم، واقعیت زندگی‌ام تقریباً غیرقابل تحمل به نظر می‌رسید."),
            StoryParagraph("I would look around my room, at the peeling wallpaper, at the dirty dishes, at the pile of books I had never finished, and I would feel a wave of despair.", "اتاقم را نگاه می‌کردم، به کاغذ دیواری کنده، به ظرف‌های کثیف، به توده کتاب‌هایی که هرگز تمام نکرده بودم و موجی از ناامیدی حس می‌کردم."),
            StoryParagraph("The contrast between my dreams and my reality was so great, so complete, so humiliating, that I could not bear to think about it.", "تضاد میان رؤیاهایم و واقعیتم آنقدر بزرگ بود، آنقدر کامل، آنقدر تحقیرآمیز که نمی‌توانستم تحمل کنم به آن فکر کنم."),
            StoryParagraph("And so I would return to my dreams, again and again, because in my dreams I was someone, and in reality I was no one.", "و بنابراین به رؤیاهایم بازمی‌گشتم، بارها و بارها، چون در رؤیاهایم کسی بودم و در واقعیت هیچ‌کس."),
            StoryParagraph("I dreamed for years; I dreamed until dreaming became my only life, my only reality, my only purpose.", "سال‌ها رؤیا دیدم؛ رؤیا دیدم تا وقتی رؤیاپردازی تنها زندگی‌ام شد، تنها واقعیتم، تنها هدفم."),
            StoryParagraph("I would dream of love, of a woman who would understand me, who would love me despite my faults, who would see in me something that no one else could see.", "رؤیای عشق می‌دیدم، رؤیای زنی که درکم می‌کرد، که با وجود عیب‌هایم دوستم می‌داشت، که در من چیزی می‌دید که هیچ‌کس دیگری نمی‌دید."),
            StoryParagraph("I would dream of friendship, of a man who would be my comrade, my equal, my brother, who would share my ideas and my feelings.", "رؤیای دوستی می‌دیدم، رؤیای مردی که همسفرم می‌بود، همتایم، برادرم، که ایده‌ها و احساساتم را شریک می‌شد."),
            StoryParagraph("I would dream of achievement, of a work that would change the world, of a contribution that would make my life meaningful.", "رؤیای دستاورد می‌دیدم، رؤیای کاری که جهان را عوض می‌کرد، رؤیای مشارکتی که زندگی‌ام را معنادار می‌کرد."),
            StoryParagraph("But the dreams were always just dreams, and the reality was always just reality, and the gap between them grew wider every year.", "اما رؤیاها همیشه فقط رؤیا بودند و واقعیت همیشه فقط واقعیت بود و شکاف میانشان هر سال پهن‌تر می‌شد."),
            StoryParagraph("And so, one day, I stopped dreaming; I simply stopped; I decided that I would no longer allow myself to escape into a world that did not exist.", "و بنابراین، یک روز، از رؤیا دیدن دست کشیدم؛ به‌سادگی دست کشیدم؛ تصمیم گرفتم دیگر به خودم اجازه ندهم به جهانی که وجود ندارد فرار کنم."),
            StoryParagraph("I decided that I would live in reality, no matter how painful that might be, no matter how unbearable.", "تصمیم گرفتم در واقعیت زندگی کنم، هر چقدر هم دردناک باشد، هر چقدر هم غیرقابل تحمل باشد."),
            StoryParagraph("But reality, when I truly faced it, was worse than I had imagined; reality was empty, and pointless, and unbearable.", "اما واقعیت، وقتی واقعاً با آن روبرو شدم، بدتر از آنچه تصور می‌کردم بود؛ واقعیت خالی بود و بی‌هدف و غیرقابل تحمل."),
            StoryParagraph("Without my dreams, I had nothing; without my illusions, I was nothing; without my escapes, I was trapped.", "بدون رؤیاهایم، هیچ داشتم؛ بدون توهماتم، هیچ بودم؛ بدون فرارهایم، گرفتار بودم."),
            StoryParagraph("And so I retreated further into the underground, into the depths of my own bitterness, into the darkness of my own consciousness.", "و بنابراین بیشتر به زیرزمین عقب‌نشینی کردم، به اعماق تلخی خودم، به تاریکی آگاهی خودم."),
            StoryParagraph("Here, in the underground, there are no dreams; there are only thoughts, endless thoughts, thoughts that circle around themselves like wounded animals.", "اینجا، در زیرزمین، رؤیایی نیست؛ تنها افکارند، افکار بی‌پایان، افکارهایی که مثل حیوانات زخمی دور خودشان می‌چرخند."),
            StoryParagraph("I think about my life, about my failures, about all the things I could have been and all the things I am not.", "به زندگی‌ام فکر می‌کنم، به شکست‌هایم، به هر چیزی که می‌توانستم باشم و هر چیزی که نیستم."),
            StoryParagraph("I think about the world, about its stupidity, about its cruelty, about all the ways in which it destroys those who cannot adapt to it.", "به جهان فکر می‌کنم، به حماقتش، به بی‌رحمی‌اش، به تمام شیوه‌هایی که کسانی که نمی‌توانند با آن سازگار شوند را نابود می‌کند."),
            StoryParagraph("I think about other people, about their happiness, about their success, about all the things they have that I do not.", "به دیگران فکر می‌کنم، به شادیشان، به موفقیتشان، به هر چیزی که دارند و من ندارم."),
            StoryParagraph("And I hate them for it; I hate them because they are happy and I am not, because they succeed and I fail, because they live and I merely exist.", "و برای این از آنها متنفرم؛ متنفرم چون خوشحالند و من نیستم، چون موفق‌اند و من شکست می‌خورم، چون زندگی می‌کنند و من فقط وجود دارم."),
            StoryParagraph("But I also hate myself for hating them; I hate myself for my pettiness, my jealousy, my inability to feel anything but spite.", "اما همچنین از خودم متنفرم که از آنها متنفرم؛ از خودم متنفرم برای حقارت، حسادت، ناتوانی‌ام از حس کردن هر چیزی جز کینه."),
            StoryParagraph("I am trapped in a circle of hatred: I hate the world, and I hate myself for hating the world, and I hate myself for hating myself.", "در دایره‌ای از نفرت گرفتارم: از جهان متنفرم و از خودم متنفرم که از جهان متنفرم و از خودم متنفرم که از خودم متنفرم."),
            StoryParagraph("There is no escape from this circle; there is only endurance, only the slow wearing away of everything that might once have been good in me.", "گریزی از این دایره نیست؛ تنها تحمل است، تنها فرسایش آهسته هر چیزی که روزی ممکن بود در من خوب باشد."),
            StoryParagraph("I could, of course, try to break the circle; I could try to love, to forgive, to accept.", "البته می‌توانستم تلاش کنم دایره را بشکنم؛ می‌توانستم تلاش کنم عشق بورزم، ببخشم، بپذیرم."),
            StoryParagraph("But I will not, out of spite. Because love would mean surrender, and surrender would mean admitting that the world is right and I am wrong.", "اما نمی‌کنم، از روی کینه. چون عشق یعنی تسلیم و تسلیم یعنی اقرار به اینکه دنیا حق دارد و من اشتباه می‌کنم."),
            StoryParagraph("And I will not admit that, because if I admit it, then my whole life has been a mistake, and I cannot bear that.", "و این را اقرار نمی‌کنم، چون اگر اقرار کنم، پس تمام زندگی‌ام اشتباه بوده و نمی‌توانم تحملش کنم."),
            StoryParagraph("So I remain in the underground, in the dark, in the cold, and I wait for the end that I know will come eventually.", "پس در زیرزمین می‌مانم، در تاریکی، در سرما و منتظر پایانی هستم که می‌دانم در نهایت می‌آید."),
            StoryParagraph("The end will come, and I will welcome it, because the end will free me from the burden of being me.", "پایان می‌آید و خوش‌آمدش می‌گویم، چون پایان بار «من بودن» را از من می‌گیرد."),
            StoryParagraph("And in the meantime, I write; I write this confession; I write these notes from the underground, because writing is the only action left to me.", "و در این بین، می‌نویسم؛ این اعتراف را می‌نویسم؛ این یادداشت‌های زیرزمینی را می‌نویسم، چون نوشتن تنها عمل باقی‌مانده برای من است."),
            StoryParagraph("Writing is a kind of revenge, a kind of defiance, a way of saying to the world: I exist, I see you, I judge you.", "نوشتن نوعی انتقام است، نوعی سرکشی، شیوه‌ای برای گفتن به جهان: من هستم، تو را می‌بینم، تو را داوری می‌کنم."),
            StoryParagraph("Even if no one reads what I write, even if these pages are thrown away or burned, they will have existed, and I will have existed, and that is something.", "حتی اگر کسی آنچه می‌نویسم را نخواند، حتی اگر این صفحات دور انداخته یا سوزانده شوند، وجود داشته‌اند و من وجود داشته‌ام و این چیزی است."),
            StoryParagraph("It is not much, but it is more than nothing, and nothing is what I would be without it.", "زیاد نیست، اما بیشتر از هیچ است و هیچ همان چیزی است که بدون آن می‌بودم."),
            StoryParagraph("So I write, and I write, and I write, and I will continue to write until I can write no more.", "پس می‌نویسم و می‌نویسم و می‌نویسم و به نوشتن ادامه می‌دهم تا وقتی دیگر نتوانم بنویسم.")
        )
    )

    // ─────────── فصل ۳: لیزا ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Liza", titlePersian = "لیزا",
        paragraphs = listOf(
            StoryParagraph("There was a time, years ago, when I used to go out into the world; I do not anymore, but once I did.", "زمانی بود، سال‌ها پیش، که به میان جهان می‌رفتم؛ دیگر نمی‌روم، اما یک بار می‌رفتم."),
            StoryParagraph("I used to visit a certain tavern, a low place, where men of the lowest sort gathered to drink and talk.", "به میخانه‌ای خاص می‌رفتم، جایی پست، جایی که مردانی از پست‌ترین نوع جمع می‌شدند تا بنوشند و صحبت کنند."),
            StoryParagraph("It was there that I met Liza, or rather, it was there that I first saw her, and later met her.", "آنجا بود که لیزا را ملاقات کردم، یا بهتر، آنجا بود که اول دیدمش و بعد ملاقاتش کردم."),
            StoryParagraph("Liza was a prostitute, a young woman of about twenty, with a sweet face and a tired look.", "لیزا روسپی بود، زن جوانی حدوداً بیست ساله، با چهره‌ای شیرین و نگاهی خسته."),
            StoryParagraph("She had not been in the profession long, and she had not yet learned the hardness that it requires, and so she still looked human.", "مدت زیادی در این حرفه نبود و هنوز سختی‌ای که لازم دارد را نیاموخته بود و بنابراین هنوز انسانی به نظر می‌رسید."),
            StoryParagraph("I noticed her the first time I went to the tavern, and I noticed her every time after that, and eventually, I spoke to her.", "اولین باری که به میخانه رفتم متوجه‌اش شدم و بعد هر بار متوجه‌اش می‌شدم و در نهایت با او صحبت کردم."),
            StoryParagraph("I do not know why I spoke to her; I do not know what I hoped to accomplish; I think, perhaps, I was simply lonely, and she was there.", "نمی‌دانم چرا با او صحبت کردم؛ نمی‌دانم امید داشتم چه کاری انجام دهم؛ فکر می‌کنم شاید تنها بودم و او آنجا بود."),
            StoryParagraph("We talked, that first time, about nothing in particular; she was shy, and I was awkward, and the conversation was difficult.", "آن بار اول، درباره هیچ چیز خاصی صحبت کردیم؛ او خجالتی بود و من دست‌وپا چلفتی و گفتگو دشوار بود."),
            StoryParagraph("But something about her drew me back, some combination of innocence and suffering, of beauty and defeat, and I came to see her again and again.", "اما چیزی درباره‌اش مرا به عقب می‌کشید، ترکیبی از معصومیت و رنج، از زیبایی و شکست و بارها و بارها به دیدارش می‌رفتم."),
            StoryParagraph("One evening, when I was particularly low, when my dreams of grandeur had collapsed and left me with nothing but despair, I decided to visit her.", "یک عصر، وقتی به‌ویژه پست بودم، وقتی رؤیاهای شکوه و عظمتم فرو ریخته بود و چیزی جز ناامیدی برایم نگذاشته بود، تصمیم گرفتم به دیدارش بروم."),
            StoryParagraph("I went to her apartment, which was small and shabby, like my own, and I sat with her, and I talked.", "به آپارتمانش رفتم که کوچک و ژنده بود، مثل آپارتمان خودم و با او نشستم و صحبت کردم."),
            StoryParagraph("I do not remember everything I said that evening, but I know that I was cruel; I know that I treated her with contempt; I know that I made her feel small.", "همه چیزهایی که آن عصر گفتم را به یاد نمی‌آورم، اما می‌دانم که بی‌رحم بودم؛ می‌دانم که با تحقیر با او رفتار کردم؛ می‌دانم که وادارش کردم حس کند کوچک است."),
            StoryParagraph("I spoke to her about her life, about her profession, about her degradation, and I did so not out of concern but out of spite.", "با او از زندگی‌اش صحبت کردم، از حرفه‌اش، از انحطاطش و این کار را نه از نگرانی بلکه از کینه کردم."),
            StoryParagraph("I wanted to hurt her, because she was there, and because she could not hurt me back; I wanted to feel powerful, because I felt powerless in every other aspect of my life.", "می‌خواستم آزارش دهم، چون آنجا بود و چون نمی‌توانست متقابلاً آزارم دهد؛ می‌خواستم قدرتمند حس کنم، چون در هر جنبه دیگری از زندگی‌ام ناتوان حس می‌کردم."),
            StoryParagraph("And I succeeded; I saw the tears in her eyes, and I saw the pain in her face, and I felt, for a moment, the satisfaction that cruelty always brings.", "و موفق شدم؛ اشک را در چشمانش دیدم و درد را در صورتش و برای لحظه‌ای، رضایتی که ظلم همیشه می‌آورد را حس کردم."),
            StoryParagraph("But then something strange happened: I felt ashamed, deeply ashamed, more ashamed than I had felt in years.", "اما بعد چیز عجیبی اتفاق افتاد: شرمنده شدم، عمیقاً شرمنده، شرمنده‌تر از آنچه سال‌ها حس کرده بودم."),
            StoryParagraph("I looked at Liza, at her tears, at her pain, and I saw, for the first time, not a prostitute, but a human being.", "به لیزا نگاه کردم، به اشک‌هایش، به دردش و برای اولین بار، نه یک روسپی بلکه یک انسان دیدم."),
            StoryParagraph("I saw a young woman who had been betrayed by life, who had been forced into a profession she hated, who had no one to turn to and no one to help her.", "زنی جوان دیدم که زندگی به او خیانت کرده بود، که به حرفه‌ای رانده شده بود که متنفرش بود، که کسی نداشت که به او روی آورد و کسی که کمکش کند."),
            StoryParagraph("And I, instead of helping her, instead of treating her with kindness, had added to her suffering; I had made her pain worse.", "و من، به جای کمک به او، به جای رفتار با مهربانی، به رنجش افزوده بودم؛ دردش را بدتر کرده بودم."),
            StoryParagraph("This realization was unbearable, and I did what I always do when something is unbearable: I fled.", "این فهم غیرقابل تحمل بود و من همان کاری را کردم که همیشه وقتی چیزی غیرقابل تحمل است می‌کنم: فرار کردم."),
            StoryParagraph("I left her apartment, and I walked home through the dark streets, and I did not look back, and I did not say goodbye.", "آپارتمانش را ترک کردم و از خیابان‌های تاریک به خانه رفتم و به عقب نگاه نکردم و خداحافظی نکردم."),
            StoryParagraph("But I did not forget her; I could not forget her; her face, her tears, her pain, haunted me for weeks.", "اما فراموشش نکردم؛ نمی‌توانستم فراموشش کنم؛ صورتش، اشک‌هایش، دردش هفته‌ها تسخیرم می‌کرد."),
            StoryParagraph("I wanted to see her again, to apologize, to try to make things right, but I could not bring myself to do it.", "می‌خواستم دوباره ببینمش، عذرخواهی کنم، تلاش کنم درستش کنم، اما نمی‌توانستم خودم را راضی کنم."),
            StoryParagraph("Because apologizing would mean admitting that I had been wrong, and admitting that I had been wrong would mean admitting that I am not the superior being I pretend to be.", "زیرا عذرخواهی یعنی اقرار به اینکه اشتباه کرده‌ام و اقرار به اشتباه یعنی اقرار به اینکه موجود برتری که تظاهر می‌کنم نیستم."),
            StoryParagraph("And so, months passed, and I did not see her; and then, one day, I learned that she had left the city.", "و بنابراین، ماه‌ها گذشت و او را ندیدم؛ و بعد، یک روز، فهمیدم شهر را ترک کرده است."),
            StoryParagraph("She had gone somewhere else, to try to start a new life, to try to escape the profession that had trapped her.", "جای دیگری رفته بود، تا زندگی جدیدی را آغاز کند، تا از حرفه‌ای که گرفتارش کرده بود بگریزد."),
            StoryParagraph("I do not know where she went; I do not know what became of her; I do not know whether she succeeded or failed.", "نمی‌دانم کجا رفت؛ نمی‌دانم بر سرش چه آمد؛ نمی‌دانم موفق شد یا شکست خورد."),
            StoryParagraph("But I think about her sometimes, even now, years later, and I wonder if I could have done something different, if I could have been kinder, if I could have helped her.", "اما گاهی به او فکر می‌کنم، حتی حالا، سال‌ها بعد و حیران می‌شوم آیا می‌توانستم کار متفاوتی بکنم، آیا می‌توانستم مهربان‌تر باشم، آیا می‌توانستم کمکش کنم."),
            StoryParagraph("And I know that I could have; I know that I should have; and I know that I did not, and that knowledge is one of the many things that keep me in the underground.", "و می‌دانم که می‌توانستم؛ می‌دانم که باید می‌کردم؛ و می‌دانم که نکردم و این دانش یکی از چیزهای بسیاری است که مرا در زیرزمین نگه می‌دارد."),
            StoryParagraph("Liza was the only person who ever loved me, or might have loved me, or could have loved me, and I destroyed whatever might have been between us.", "لیزا تنها کسی بود که هرگز دوستم داشت، یا ممکن بود دوستم داشته باشد، یا می‌توانست دوستم داشته باشد و من هر چیزی که می‌توانست میانمان باشد را نابود کردم."),
            StoryParagraph("Not because I did not want her love, but because I did not know how to accept it; not because I did not feel anything, but because I felt too much and could not bear it.", "نه چون عشقش را نمی‌خواستم، بلکه چون نمی‌دانستم چطور بپذیرمش؛ نه چون چیزی حس نمی‌کردم، بلکه چون بیش از حد حس می‌کردم و نمی‌توانستم تحملش کنم."),
            StoryParagraph("This is the tragedy of the underground man: that he destroys every chance at happiness, that he pushes away everyone who tries to love him, that he chooses misery over joy, isolation over connection, death over life.", "این تراژدی مرد زیرزمینی است: هر فرصت خوشبختی را نابود می‌کند، هر کسی که تلاش می‌کند دوستش بدارد را می‌راند، بدبختی را بر شادی ترجیح می‌دهد، انزوا را بر ارتباط، مرگ را بر زندگی."),
            StoryParagraph("And he does this not because he is evil, but because he is afraid: afraid of being hurt, afraid of being rejected, afraid of being loved.", "و این کار را نه چون شرور است می‌کند، بلکه چون می‌ترسد: از آزرده شدن می‌ترسد، از رد شدن، از دوست داشته شدن."),
            StoryParagraph("Liza knew this; Liza understood this; Liza, in her simple, uneducated way, understood more about me than I understood about myself.", "لیزا این را می‌دانست؛ لیزا این را می‌فهمید؛ لیزا، به شیوه ساده و بی‌سوادش، بیشتر درباره من می‌فهمید از آنچه من درباره خودم می‌فهمیدم."),
            StoryParagraph("And she loved me anyway; she loved me despite my cruelty, despite my spite, despite everything.", "و با این حال دوستم داشت؛ با وجود بی‌رحمی‌ام دوستم داشت، با وجود کینه‌ام، با وجود همه چیز."),
            StoryParagraph("I think about her often, and I wonder if she ever found the happiness I could not give her, if she ever found a man who could love her as she deserved to be loved.", "اغلب به او فکر می‌کنم و حیرانم آیا هرگز آن خوشبختی‌ای که نتوانستم به او بدهم را یافت، آیا هرگز مردی یافت که بتواند آنطور که سزاوار بود دوستش بدارد."),
            StoryParagraph("I hope she did; I hope she found peace; I hope she found love.", "امیدوارم یافته باشد؛ امیدوارم آرامش یافته باشد؛ امیدوارم عشق یافته باشد."),
            StoryParagraph("And I hope, though I know it is impossible, that she has forgiven me, that she remembers me not with bitterness but with pity, that she understands that I could not help being what I am.", "و امیدوارم، هرچند می‌دانم ناممکن است، که بخشیده باشد، که نه با تلخی بلکه با ترحم به یادم آورد، که بفهمد نمی‌توانستم چیزی جز آنچه هستم باشم."),
            StoryParagraph("But I do not deserve her forgiveness; I do not deserve her pity; I do not deserve anything but the misery I have created for myself.", "اما سزاوار بخشش او نیستم؛ سزاوار ترحمش نیستم؛ سزاوار چیزی نیستم جز بدبختی‌ای که برای خودم ساخته‌ام.")
        )
    )

    // ─────────── فصل ۴: خودفریبی ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Self-Deception", titlePersian = "خودفریبی",
        paragraphs = listOf(
            StoryParagraph("I have been writing these notes for some time now, and I have been trying to be honest, but I wonder if I have succeeded.", "مدتی است این یادداشت‌ها را می‌نویسم و تلاش کرده‌ام صادق باشم، اما حیرانم آیا موفق شده‌ام."),
            StoryParagraph("The truth is that I am not sure I know what honesty is, or whether it is even possible, or whether I have ever truly been honest with myself.", "حقیقت این است که مطمئن نیستم می‌دانم صداقت چیست، یا آیا اصلاً ممکن است، یا آیا هرگز به‌راستی با خودم صادق بوده‌ام."),
            StoryParagraph("I have told myself so many stories over the years, so many justifications, so many rationalizations, that I no longer know what is true and what I have invented.", "سال‌ها اینقدر داستان به خودم گفته‌ام، اینقدر توجیه، اینقدر دلیل‌تراشی که دیگر نمی‌دانم چه درست است و چه ساخته‌ام."),
            StoryParagraph("I have told myself that I am superior to others, and I have told myself that I am inferior; I have told myself that I am a genius, and I have told myself that I am a fool.", "به خودم گفته‌ام از دیگران برترم و به خودم گفته‌ام از آن‌ها پایین‌ترم؛ به خودم گفته‌ام نابغه‌ام و به خودم گفته‌ام احمقم."),
            StoryParagraph("I have told myself that I am a victim of the world, and I have told myself that I am the author of my own misery; I have told myself that I am innocent, and I have told myself that I am guilty.", "به خودم گفته‌ام قربانی جهانم و به خودم گفته‌ام نویسنده بدبختی خودمم؛ به خودم گفته‌ام بی‌گناهم و به خودم گفته‌ام گناهکارم."),
            StoryParagraph("Which of these is true? Perhaps all of them, perhaps none of them, perhaps some combination that I cannot untangle.", "کدام‌شان درست است؟ شاید همه، شاید هیچ‌کدام، شاید ترکیبی که نمی‌توانم بازش کنم."),
            StoryParagraph("The truth is that I do not know myself; I have never known myself; and I suspect that I never will.", "حقیقت این است که خودم را نمی‌شناسم؛ هرگز خودم را نشناخته‌ام؛ و مشکوکم که هرگز خواهم شناخت."),
            StoryParagraph("This is perhaps the deepest truth of the underground: that we do not know who we are, that we are mysteries to ourselves, that we live our entire lives in a state of fundamental self-ignorance.", "این شاید عمیق‌ترین حقیقت زیرزمین باشد: ما نمی‌دانیم که هستیم، برای خودمان معما هستیم، تمام زندگی‌مان را در وضعیتی از نادانی بنیادین نسبت به خود می‌گذرانیم."),
            StoryParagraph("We tell ourselves that we know our motivations, but we do not; we tell ourselves that we understand our desires, but we do not; we tell ourselves that we control our actions, but we do not.", "به خودمان می‌گوییم انگیزه‌هایمان را می‌دانیم، اما نمی‌دانیم؛ به خودمان می‌گوییم امیالمان را می‌فهمیم، اما نمی‌فهمیم؛ به خودمان می‌گوییم اعمالمان را کنترل می‌کنیم، اما نمی‌کنیم."),
            StoryParagraph("The truth is that we are driven by forces we do not understand, toward ends we cannot see, and the story we tell about ourselves is nothing more than a story.", "حقیقت این است که توسط نیروهایی که نمی‌فهمیم رانده می‌شویم، به سمت اهدافی که نمی‌بینیم و داستانی که درباره خودمان تعریف می‌کنیم چیزی بیش از یک داستان نیست."),
            StoryParagraph("Consider, for example, my spite. Why am I spiteful? What purpose does it serve? What do I gain from it?", "مثلاً کینه‌ام را در نظر بگیرید. چرا کینه‌توزم؟ چه هدفی را خدمت می‌کند؟ از آن چه به دست می‌آورم؟"),
            StoryParagraph("I have told myself that spite is a form of rebellion, a way of refusing to accept a world that is unacceptable.", "به خودم گفته‌ام کینه نوعی شورش است، شیوه‌ای برای امتناع از پذیرش جهانی که غیرقابل قبول است."),
            StoryParagraph("But this is a lie; spite is not rebellion; spite is merely a form of self-indulgence, a way of feeling important without doing anything important.", "اما این دروغ است؛ کینه شورش نیست؛ کینه صرفاً نوعی خودارضایی است، شیوه‌ای برای حس اهمیت بدون انجام کار مهمی."),
            StoryParagraph("Consider, another example, my intelligence. Why am I intelligent? What good has it done me? Has it made me happy? Has it made me successful? Has it made me loved?", "مثال دیگر، هوشم را در نظر بگیرید. چرا باهوشم؟ چه فایده‌ای به من رسانده؟ خوشحالم کرده؟ موفقم کرده؟ دوست‌داشتنی‌ام کرده؟"),
            StoryParagraph("No, it has not; it has only made me more aware of my own misery, more conscious of my own failures, more sensitive to my own suffering.", "نه، نکرده؛ تنها آگاه‌ترم کرده از بدبختی خودم، آگاه‌تر از شکست‌هایم، حساس‌تر به رنج خودم."),
            StoryParagraph("Intelligence, without the ability to act, is a curse; intelligence, without the courage to love, is a burden; intelligence, without the will to live, is a slow death.", "هوش، بدون توانایی عمل، نفرین است؛ هوش، بدون شجاعت عشق ورزیدن، بار است؛ هوش، بدون اراده زندگی کردن، مرگی آهسته است."),
            StoryParagraph("Consider, a third example, my isolation. Why am I isolated? Why do I push people away? Why do I refuse to participate in the world?", "مثال سوم، انزوایم را در نظر بگیرید. چرا منزوی‌ام؟ چرا مردم را می‌رانم؟ چرا از مشارکت در جهان امتناع می‌کنم؟"),
            StoryParagraph("I have told myself that isolation is a choice, a way of protecting myself from a world that would hurt me.", "به خودم گفته‌ام انزوا انتخابی است، شیوه‌ای برای محافظت از خودم در برابر جهانی که آزارم می‌دهد."),
            StoryParagraph("But this is also a lie; isolation is not a choice; isolation is a prison, and I am not the warden, I am the prisoner.", "اما این هم دروغ است؛ انزوا انتخاب نیست؛ انزوا زندان است و من زندانبان نیستم، زندانی‌ام."),
            StoryParagraph("I did not choose to be isolated; I chose to push people away, and isolation was the consequence; I did not choose to be miserable; I chose to refuse happiness, and misery was the consequence.", "انتخاب نکردم منزوی باشم؛ انتخاب کردم مردم را برانم و انزوا نتیجه بود؛ انتخاب نکردم بدبخت باشم؛ انتخاب کردم خوشبختی را رد کنم و بدبختی نتیجه بود."),
            StoryParagraph("I have spent my entire life pretending that I am the master of my fate, but the truth is that I am the slave of my own habits.", "تمام عمرم را صرف تظاهر کردم که ارباب سرنوشتم، اما حقیقت این است که برده عادت‌های خودمم."),
            StoryParagraph("I have spent my entire life pretending that I am superior to other men, but the truth is that I am merely different, and difference is not superiority.", "تمام عمرم را صرف تظاهر کردم که از دیگران برترم، اما حقیقت این است که تنها متفاوتم و تفاوت برتری نیست."),
            StoryParagraph("I have spent my entire life pretending that I do not care about anything, but the truth is that I care desperately, and I cannot bear to admit it.", "تمام عمرم را صرف تظاهر کردم که به هیچ چیز اهمیت نمی‌دهم، اما حقیقت این است که ناامیدانه اهمیت می‌دهم و نمی‌توانم تحمل کنم اقرارش کنم."),
            StoryParagraph("Because admitting that I care would mean admitting that I am vulnerable, and admitting that I am vulnerable would mean admitting that I can be hurt.", "زیرا اقرار به اهمیت دادن یعنی اقرار به آسیب‌پذیر بودن و اقرار به آسیب‌پذیری یعنی اقرار به اینکه می‌توانم آزرده شوم."),
            StoryParagraph("And I cannot bear to be hurt; I cannot bear to be rejected; I cannot bear to be abandoned.", "و نمی‌توانم تحمل کنم آزرده شوم؛ نمی‌توانم تحمل کنم رد شوم؛ نمی‌توانم تحمل کنم رها شوم."),
            StoryParagraph("So I push people away before they can push me away; I hurt people before they can hurt me; I abandon people before they can abandon me.", "پس مردم را می‌رانم پیش از آنکه آن‌ها برانم؛ به مردم آسیب می‌زنم پیش از آنکه آن‌ها آسیب بزنند؛ مردم را رها می‌کنم پیش از آنکه آن‌ها رهایم کنند."),
            StoryParagraph("This is the strategy of the underground man: to hurt before being hurt, to reject before being rejected, to destroy before being destroyed.", "این استراتژی مرد زیرزمینی است: آزردن پیش از آزرده شدن، رد کردن پیش از رد شدن، نابود کردن پیش از نابود شدن."),
            StoryParagraph("It is a strategy that works, in a way: it protects me from the pain of being hurt by others.", "استراتژی‌ای است که به نوعی کار می‌کند: از من در برابر درد آزرده شدن توسط دیگران محافظت می‌کند."),
            StoryParagraph("But it also prevents me from experiencing the joy of connection, the warmth of love, the peace of acceptance.", "اما همچنین مانعم می‌شود از تجربه کردن شادی ارتباط، گرمای عشق، آرامش پذیرش."),
            StoryParagraph("I have traded happiness for safety, and I have paid too high a price; I have traded love for security, and I have gotten neither.", "شادی را با امنیت معامله کرده‌ام و بهای بیش از حد بالایی پرداخته‌ام؛ عشق را با امنیت معامله کرده‌ام و هیچ‌کدام را نیافته‌ام."),
            StoryParagraph("And yet, even knowing this, even seeing clearly the trap I have built for myself, I cannot escape it.", "و با این حال، حتی با دانستن این، حتی با دیدن واضح تله‌ای که برای خودم ساخته‌ام، نمی‌توانم از آن بگریزم."),
            StoryParagraph("Because escape would require trust, and I do not trust; escape would require hope, and I do not hope; escape would require love, and I do not love.", "زیرا فرار اعتماد می‌خواهد و اعتماد نمی‌کنم؛ فرار امید می‌خواهد و امید ندارم؛ فرار عشق می‌خواهد و عشق نمی‌ورزم."),
            StoryParagraph("Or rather, I cannot bring myself to trust, to hope, to love; the capacity is there, buried somewhere deep inside me, but I cannot reach it.", "یا بهتر، نمی‌توانم خودم را راضی کنم اعتماد کنم، امید داشته باشم، عشق بورزم؛ ظرفیت آنجاست، جایی عمیق درونم دفن شده اما نمی‌توانم به آن برسم."),
            StoryParagraph("I am, in the deepest sense, a prisoner of my own mind, and I have been so for so long that I no longer remember what freedom might look like.", "من به عمیق‌ترین معنا زندانی ذهن خودمم و آنقدر طولانی چنین بوده‌ام که دیگر به یاد نمی‌آورم آزادی چه شکلی می‌تواند باشد."),
            StoryParagraph("This is the underground: not a place, but a state of mind; not a prison, but a habit of despair; not a fate, but a choice that has been made so many times that it has become a fate.", "این زیرزمین است: نه مکان، بلکه حالتی ذهنی؛ نه زندان، بلکه عادتی از ناامیدی؛ نه سرنوشت، بلکه انتخابی که آنقدر بارها انجام شده که به سرنوشت تبدیل شده."),
            StoryParagraph("And I, who could have been anything, who could have been happy, who could have been loved, am nothing, am miserable, am alone.", "و من که می‌توانستم هر چیزی باشم، می‌توانستم خوشحال باشم، می‌توانستم دوست داشته شوم، هیچم، بدبختم، تنهایم."),
            StoryParagraph("This is the confession of the underground man: that he has destroyed his own life, not through any external force but through his own choices, and that he will continue to destroy it, because destruction has become his only comfort.", "این اعتراف مرد زیرزمینی است: او زندگی خودش را نابود کرده، نه از طریق هیچ نیروی بیرونی، بلکه از طریق انتخاب‌های خودش و به نابود کردنش ادامه می‌دهد، چون نابودی تنها تسلی‌اش شده است.")
        )
    )

    // ─────────── فصل ۵: انسان قرن نوزدهم ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Man of the Nineteenth Century", titlePersian = "انسان قرن نوزدهم",
        paragraphs = listOf(
            StoryParagraph("I have been called a man of the nineteenth century, and perhaps that is accurate, and perhaps it is not.", "مرا مرد قرن نوزدهم نامیده‌اند و شاید این دقیق باشد و شاید نه."),
            StoryParagraph("What does it mean to be a man of the nineteenth century? It means to be a man of contradictions, a man who believes in progress and doubts it, a man who embraces reason and rejects it, a man who longs for meaning and fears it.", "مرد قرن نوزدهم بودن یعنی چه؟ یعنی مردی از تناقض‌ها بودن، مردی که به پیشرفت باور دارد و شکش می‌کند، مردی که عقل را در آغوش می‌گیرد و ردش می‌کند، مردی که مشتاق معناست و از آن می‌ترسد."),
            StoryParagraph("The nineteenth century was an age of science, of industry, of empire; it was an age that believed, with a confidence that now seems almost touching, that all problems could be solved by reason.", "قرن نوزدهم عصر علم بود، صنعت، امپراتوری؛ عصری بود که با اطمینانی که حالا تقریباً لمس‌کننده به نظر می‌رسد باور داشت همه مشکلات با عقل قابل حل‌اند."),
            StoryParagraph("But beneath the confidence was a darkness, a despair, a sense that the old certainties were crumbling and the new ones had not yet been born.", "اما زیر آن اطمینان، تاریکی بود، ناامیدی، حسی که یقین‌های قدیم فرو می‌ریزند و یقین‌های جدید هنوز زاده نشده‌اند."),
            StoryParagraph("I am a product of that age, and the contradictions of that age are my contradictions; the despair of that age is my despair.", "من محصول آن عصرم و تناقض‌های آن عصر تناقض‌های منند؛ ناامیدی آن عصر ناامیدی من است."),
            StoryParagraph("I believe in reason, and I know that reason cannot answer the deepest questions of human existence.", "به عقل باور دارم و می‌دانم که عقل نمی‌تواند عمیق‌ترین پرسش‌های وجود انسانی را پاسخ دهد."),
            StoryParagraph("I believe in progress, and I know that progress has brought as much misery as happiness, as much destruction as creation.", "به پیشرفت باور دارم و می‌دانم که پیشرفت به همان اندازه شادی بدبختی آورده، همانقدر نابودی که آفرینش."),
            StoryParagraph("I believe in science, and I know that science, without wisdom, is merely a more sophisticated form of barbarism.", "به علم باور دارم و می‌دانم که علم، بدون خرد، تنها شکل پیچیده‌تری از بربریت است."),
            StoryParagraph("I am, in short, a modern man; I am a man who has been given everything and believes in nothing; I am a man who knows everything and understands nothing.", "خلاصه، مردی مدرنم؛ مردی که همه چیز به او داده شده و به هیچ چیز باور ندارد؛ مردی که همه چیز می‌داند و هیچ نمی‌فهمد."),
            StoryParagraph("This is the curse of the modern world: that we have developed our intellects to an extraordinary degree while our souls remain as undeveloped as those of our ancestors.", "این نفرین دنیای مدرن است: عقل‌هایمان را به درجه‌ای فوق‌العاده توسعه داده‌ایم در حالی که روح‌هایمان به همان اندازه توسعه‌نیافته مانده که روح نیاکانمان."),
            StoryParagraph("We can split the atom; we cannot understand why we are unhappy. We can travel to the moon; we cannot find meaning on earth. We can communicate with anyone on the planet; we cannot communicate with ourselves.", "می‌توانیم اتم را بشکافیم؛ نمی‌توانیم بفهمیم چرا ناخوشحالیم. می‌توانیم به ماه سفر کنیم؛ نمی‌توانیم روی زمین معنا بیابیم. می‌توانیم با هر کسی روی سیاره ارتباط برقرار کنیم؛ نمی‌توانیم با خودمان ارتباط برقرار کنیم."),
            StoryParagraph("The underground man is a modern man because he lives in this contradiction; he is educated, intelligent, aware, and yet he cannot find a way to live.", "مرد زیرزمینی مردی مدرن است چون در این تناقض زندگی می‌کند؛ تحصیل‌کرده است، باهوش، آگاه و با این حال نمی‌تواند راهی برای زندگی بیابد."),
            StoryParagraph("He has read all the books, and the books have not helped him; he has studied all the philosophies, and the philosophies have not helped him; he has explored all the religions, and the religions have not helped him.", "همه کتاب‌ها را خوانده و کتاب‌ها کمکش نکرده‌اند؛ همه فلسفه‌ها را مطالعه کرده و فلسفه‌ها کمکش نکرده‌اند؛ همه دین‌ها را بررسی کرده و دین‌ها کمکش نکرده‌اند."),
            StoryParagraph("He knows everything, and he knows nothing; he understands everything, and he understands nothing; he has seen everything, and he has seen nothing.", "همه چیز می‌داند و هیچ نمی‌داند؛ همه چیز را می‌فهمد و هیچ نمی‌فهمد؛ همه چیز را دیده و هیچ ندیده."),
            StoryParagraph("And so he retreats into himself; and so he retreats into the underground; and so he waits, endlessly, hopelessly, for something that will never come.", "و بنابراین به خودش عقب‌نشینی می‌کند؛ به زیرزمین؛ و منتظر می‌ماند، بی‌پایان، ناامیدانه، برای چیزی که هرگز نمی‌آید."),
            StoryParagraph("But I am not only a modern man; I am also a Russian man; and to be a Russian man is to be doubly divided.", "اما من تنها مردی مدرن نیستم؛ مردی روس هم هستم و مرد روس بودن یعنی دو برابر تقسیم شده بودن."),
            StoryParagraph("The Russian soul has always been divided between East and West, between the old ways and the new, between the tradition of faith and the tradition of doubt.", "روح روسی همیشه بین شرق و غرب تقسیم شده، بین راه‌های قدیم و جدید، بین سنت ایمان و سنت شک."),
            StoryParagraph("We looked to Europe for enlightenment, and Europe gave us ideas that we could not digest; we looked to our own traditions for roots, and our own traditions had been weakened by centuries of suffering.", "به اروپا نگاه کردیم برای روشنگری و اروپا ایده‌هایی به ما داد که نمی‌توانستیم هضمشان کنیم؛ به سنت‌های خودمان نگاه کردیم برای ریشه‌ها و سنت‌های خودمان با قرن‌ها رنج ضعیف شده بودند."),
            StoryParagraph("And so we became a people of contradictions: a people who believe in God and doubt Him, who love their country and hate it, who long for community and cannot form it.", "و بنابراین مردمی از تناقض‌ها شدیم: مردمی که به خدا باور دارند و شکش می‌کنند، که کشورشان را دوست دارند و از آن متنفرند، که مشتاق جامعه‌اند و نمی‌توانند شکلش دهند."),
            StoryParagraph("The underground man is a Russian man because he lives in this division; because he is torn between two worlds and belongs to neither; because he cannot be at peace with himself or with his country.", "مرد زیرزمینی مردی روس است چون در این تقسیم زندگی می‌کند؛ چون بین دو جهان پاره شده و به هیچ‌کدام تعلق ندارد؛ چون نمی‌تواند با خودش یا با کشورش در صلح باشد."),
            StoryParagraph("This is the tragedy of Russia, and it is the tragedy of every nation that has been forced to choose between the past and the future, between its own soul and the soul of the world.", "این تراژدی روسیه است و تراژدی هر ملتی که مجبور شده بین گذشته و آینده انتخاب کند، بین روح خودش و روح جهان."),
            StoryParagraph("But I do not write these notes to explain Russia, or to explain the nineteenth century, or to explain anything at all.", "اما این یادداشت‌ها را نمی‌نویسم تا روسیه را توضیح دهم، یا قرن نوزدهم را، یا اصلاً چیزی را."),
            StoryParagraph("I write them because I must; because there is something inside me that will not be silent; because the words accumulate in my mind like water behind a dam, and if I do not let them out, I will drown.", "آن‌ها را می‌نویسم چون مجبورم؛ چون چیزی درونم هست که ساکت نمی‌شود؛ چون کلمات مثل آب پشت سد در ذهنم جمع می‌شوند و اگر بیرونشان ندهم، غرق می‌شوم."),
            StoryParagraph("I write them for myself, first of all, as a kind of therapy, as a way of organizing the chaos of my thoughts.", "نخست از همه برای خودم می‌نویسم، نوعی درمان، شیوه‌ای برای سازمان دادن آشوب افکارم."),
            StoryParagraph("But I also write them for anyone who might read them, anyone who might recognize in my suffering a reflection of their own, anyone who might find, in these pages, a kind of company.", "اما برای هر کسی هم می‌نویسم که ممکن است بخواندشان، هر کسی که ممکن است در رنج من بازتاب خودش را تشخیص دهد، هر کسی که ممکن است در این صفحات نوعی همراهی بیابد."),
            StoryParagraph("Because we are all underground men, in our own ways; we are all divided, isolated, confused; we are all looking for something we cannot name.", "زیرا همه‌مان به شیوه‌های خودمان مردان زیرزمینی هستیم؛ همه‌مان تقسیم‌شده، منزوی، گیج؛ همه‌مان دنبال چیزی می‌گردیم که نمی‌توانیم نامش را ببریم."),
            StoryParagraph("And if these notes help even one person to feel less alone, then they will have served their purpose.", "و اگر این یادداشت‌ها حتی به یک نفر کمک کنند کمتر تنها حس کند، پس هدفشان را خدمت کرده‌اند."),
            StoryParagraph("But I do not expect that; I do not expect anything; I have learned, over the years, not to expect.", "اما انتظارش را ندارم؛ انتظار هیچ چیز را ندارم؛ در طول سال‌ها آموخته‌ام انتظار نداشته باشم."),
            StoryParagraph("And yet I write, and I will continue to write, because writing is the only thing I know how to do, and because stopping would mean accepting that there is no point in anything.", "و با این حال می‌نویسم و به نوشتن ادامه می‌دهم، چون نوشتن تنها کاری است که می‌دانم چطور بکنم و چون توقف یعنی پذیرش اینکه هیچ چیز فایده‌ای ندارد."),
            StoryParagraph("And that, I cannot accept; even now, even in the underground, even in the depths of my despair, I cannot accept that there is no point.", "و این را نمی‌توانم بپذیرم؛ حتی حالا، حتی در زیرزمین، حتی در اعماق ناامیدی‌ام، نمی‌توانم بپذیرم که فایده‌ای نیست."),
            StoryParagraph("Because to accept that would be to give up, and I will not give up, out of spite if nothing else.", "زیرا پذیرش این یعنی تسلیم شدن و تسلیم نمی‌شوم، از روی کینه اگر نه برای هیچ چیز دیگر."),
            StoryParagraph("So I write, and the words accumulate, and the pages multiply, and I continue to exist.", "پس می‌نویسم و کلمات جمع می‌شوند و صفحات زیاد می‌شوند و به وجودم ادامه می‌دهم."),
            StoryParagraph("And that, perhaps, is all I can ask for: to continue to exist, to continue to struggle, to continue to be, until the end comes.", "و این، شاید، تمام چیزی است که می‌توانم بخواهم: ادامه وجود، ادامه مبارزه، ادامه بودن، تا وقتی پایان بیاید.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Notes from Underground, published in 1864, is one of the most important works of nineteenth-century literature, and one of the most influential.", "یادداشت‌های زیرزمینی، منتشرشده در ۱۸۶۴، یکی از مهم‌ترین آثار ادبیات قرن نوزدهم و یکی از تأثیرگذارترین است."),
            StoryParagraph("It is a short novel, barely a hundred pages, but in those pages Dostoevsky invented a new kind of character, a new kind of narration, a new kind of literature.", "رمانی کوتاه است، به‌سختی صد صفحه، اما در آن صفحات داستایفسکی نوع جدیدی از شخصیت، نوع جدیدی از روایت، نوع جدیدی از ادبیات ابداع کرد."),
            StoryParagraph("The underground man is the first anti-hero of modern literature: a man who is intelligent, educated, and completely unable to function in society.", "مرد زیرزمینی نخستین ضدقهرمان ادبیات مدرن است: مردی که باهوش، تحصیل‌کرده و کاملاً ناتوان از کار کردن در جامعه است."),
            StoryParagraph("He is not a victim of poverty, or oppression, or misfortune; he is a victim of his own consciousness, of his own awareness, of his own intelligence.", "او قربانی فقر نیست، نه ستم، نه بدبیاری؛ قربانی آگاهی خودش است، آگاهی‌اش، هوشش."),
            StoryParagraph("He sees everything, and understands everything, and cannot do anything; he knows what he should do, and he does not do it; he knows what he should not do, and he does it anyway.", "او همه چیز را می‌بیند و همه چیز را می‌فهمد و نمی‌تواند هیچ کاری بکند؛ می‌داند چه باید بکند و نمی‌کند؛ می‌داند چه نباید بکند و به هر حال می‌کند."),
            StoryParagraph("He is, in other words, a modern man; and that is why the novel has been so influential, because it captures, with uncanny precision, the spiritual condition of our age.", "به عبارت دیگر، او مردی مدرن است و به همین دلیل رمان اینقدر تأثیرگذار بوده، چون با دقتی شبح‌آسا وضعیت روحی عصر ما را ثبت می‌کند."),
            StoryParagraph("Dostoevsky wrote the novel in response to a specific political and philosophical situation: the rise of rationalism, the rise of materialism, the rise of the utopian socialism that was then fashionable in Russia.", "داستایفسکی رمان را در پاسخ به وضعیت سیاسی و فلسفی خاصی نوشت: ظهور عقل‌گرایی، ظهور ماتریالیسم، ظهور سوسیالیسم اتوپایی که آن موقع در روسیه مد بود."),
            StoryParagraph("The utopian socialists believed that if you organized society according to rational principles, everyone would be happy; if you educated people, they would become good.", "سوسیالیست‌های اتوپایی باور داشتند اگر جامعه را بر اساس اصول عقلانی سازمان دهی کنی، همه خوشحال می‌شوند؛ اگر مردم را آموزش دهی، خوب می‌شوند."),
            StoryParagraph("Dostoevsky's underground man is a refutation of this belief; he is a man who has been educated, who understands rational principles, who knows exactly what he should do to be happy—and who refuses to do it.", "مرد زیرزمینی داستایفسکی رد این باور است؛ او مردی است که آموزش دیده، اصول عقلانی را می‌فهمد، دقیقاً می‌داند چه باید بکند تا خوشحال باشد—و از انجامش امتناع می‌کند."),
            StoryParagraph("Why does he refuse? Because, Dostoevsky suggests, human beings are not rational creatures; we do not always act in our own interest; sometimes we act out of spite, out of perversity, out of the sheer pleasure of refusing to be rational.", "چرا امتناع می‌کند؟ چون، داستایفسکی پیشنهاد می‌دهد، انسان‌ها مخلوقات عقلانی نیستند؛ همیشه به نفع خودمان عمل نمی‌کنیم؛ گاهی از روی کینه عمل می‌کنیم، از لجاجت، از لذت محض امتناع از عقلانی بودن."),
            StoryParagraph("The underground man says: 'I want to live according to my own stupid will; I want to be capricious; I want to be free.'", "مرد زیرزمینی می‌گوید: «می‌خواهم مطابق اراده احمقانه خودم زندگی کنم؛ می‌خواهم هوس‌باز باشم؛ می‌خواهم آزاد باشم.»"),
            StoryParagraph("And this, Dostoevsky suggests, is the deepest truth about human beings: that we are not machines, that we cannot be reduced to formulas, that we will always rebel against any system that tries to contain us.", "و این، داستایفسکی پیشنهاد می‌دهد، عمیق‌ترین حقیقت درباره انسان‌ها است: ما ماشین نیستیم، نمی‌توان به فرمول تقلیل‌مان داد، همیشه علیه هر نظامی که تلاش کند دربرمان بگیرد شورش می‌کنیم."),
            StoryParagraph("The novel is also, and perhaps more importantly, a study of human psychology, of the depths of the human soul, of the contradictions that lie at the heart of every human being.", "رمان همچنین، و شاید مهم‌تر، مطالع‌ای است درباره روانشناسی انسانی، درباره اعماق روح انسانی، درباره تناقض‌هایی که در قلب هر انسانی هستند."),
            StoryParagraph("The underground man is both proud and humble, both intelligent and foolish, both cruel and tender, both cruel and compassionate.", "مرد زیرزمینی همزمان مغرور و فروتن است، باهوش و احمق، بی‌رحم و لطیف، بی‌رحم و شفیق."),
            StoryParagraph("He loves humanity and hates it; he longs for connection and refuses it; he wants to be happy and chooses misery.", "او بشریت را دوست دارد و از آن متنفر است؛ مشتاق ارتباط است و ردش می‌کند؛ می‌خواهد خوشحال باشد و بدبختی را برمی‌گزیند."),
            StoryParagraph("He is, in short, a human being, and that is why readers have found him so compelling, so disturbing, so recognizable.", "خلاصه، او یک انسان است و به همین دلیل خوانندگان او را اینقدر جذاب، اینقدر نگران‌کننده، اینقدر قابل تشخیص یافته‌اند."),
            StoryParagraph("We see ourselves in the underground man, whether we want to or not; we recognize his contradictions as our own; we feel his isolation as our own.", "خودمان را در مرد زیرزمینی می‌بینیم، خواه بخواهیم خواه نه؛ تناقض‌هایش را همچون تناقض‌های خودمان تشخیص می‌دهیم؛ انزوایش را همچون انزوای خودمان حس می‌کنیم."),
            StoryParagraph("And yet, at the same time, we are repelled by him, because he shows us something about ourselves that we would rather not see: our own capacity for self-destruction, our own willingness to choose misery over happiness, our own inability to love.", "و با این حال، در همان زمان، از او دفع می‌شویم، چون چیزی درباره خودمان نشانمان می‌دهد که ترجیح می‌دهیم نبینیم: ظرفیت خودمان برای خود-نابودی، آمادگی‌مان برای برگزیدن بدبختی بر شادی، ناتوانی‌مان از عشق."),
            StoryParagraph("The novel is also a meditation on freedom, on what it means to be free, on whether freedom is a blessing or a curse.", "رمان همچنین مراقبه‌ای است درباره آزادی، درباره اینکه آزاد بودن یعنی چه، درباره اینکه آزادی نعمت است یا نفرین."),
            StoryParagraph("The underground man is free; he is free from the constraints of society, from the expectations of others, from the demands of convention.", "مرد زیرزمینی آزاد است؛ آزاد از محدودیت‌های جامعه، از انتظارات دیگران، از خواسته‌های عرف."),
            StoryParagraph("But his freedom is also his prison; it isolates him from others; it prevents him from participating in the life around him; it condemns him to a solitude that he cannot bear.", "اما آزادی‌اش زندانش هم هست؛ او را از دیگران منزوی می‌کند؛ مانعش می‌شود از مشارکت در زندگی اطرافش؛ محکومش می‌کند به تنهایی‌ای که نمی‌تواند تحمل کند."),
            StoryParagraph("This is the paradox of freedom: that the more free we become, the more we risk losing the connections that give life meaning.", "این پارادوکس آزادی است: هرچه آزادتر می‌شویم، بیشتر خطر از دست دادن ارتباطاتی را داریم که به زندگی معنا می‌دهند."),
            StoryParagraph("And yet, the alternative—surrender of freedom, submission to authority, acceptance of what we are told to think and feel—is even worse.", "و با این حال، گزینه دیگر—تسلیم آزادی، تسلیم به اقتدار، پذیرش آنچه به ما گفته می‌شود فکر و حس کنیم—حتی بدتر است."),
            StoryParagraph("The underground man may be miserable, but he is at least himself; he may be alone, but he is at least not a slave.", "مرد زیرزمینی ممکن است بدبخت باشد، اما دست‌کم خودش است؛ ممکن است تنها باشد، اما دست‌کم برده نیست."),
            StoryParagraph("And this, Dostoevsky suggests, is the only dignity available to us: to be ourselves, no matter how painful that may be; to be free, no matter how lonely that may be.", "و این، داستایفسکی پیشنهاد می‌دهد، تنها کرامت موجود برای ماست: خودمان بودن، هر چقدر هم دردناک؛ آزاد بودن، هر چقدر هم تنها."),
            StoryParagraph("Notes from Underground is not a comforting book; it offers no solutions, no hope, no redemption.", "یادداشت‌های زیرزمینی کتاب تسلی‌بخشی نیست؛ هیچ راه‌حلی ارائه نمی‌دهد، نه امیدی، نه رستگاری."),
            StoryParagraph("It is a diagnosis, not a cure; it is a mirror, not a window; it is a descent into the depths, not an ascent to the heights.", "تشخیص است، نه درمان؛ آینه است، نه پنجره؛ نزولی است به اعماق، نه صعودی به قله‌ها."),
            StoryParagraph("But it is also, in its own way, hopeful, because it shows us that we are not alone in our suffering, that others have felt what we feel, that the underground is a place that all of us visit at some point in our lives.", "اما به شیوه خودش، امیدبخش هم هست، چون نشانمان می‌دهد در رنجمان تنها نیستیم، دیگران همانی را حس کرده‌اند که ما حس می‌کنیم، زیرزمین جایی است که همه ما در نقطه‌ای از زندگی‌مان بازدیدش می‌کنیم."),
            StoryParagraph("And if we do not remain there forever—if we find our way back to the surface, back to the light, back to the world of other people—it is because we have learned something from the underground.", "و اگر برای همیشه آنجا نمی‌مانیم—اگر راهی به سطح، به نور، به جهان دیگران می‌یابیم—به این دلیل است که چیزی از زیرزمین آموخته‌ایم."),
            StoryParagraph("We have learned that the greatest challenge of human life is not to be happy, but to be present; not to be successful, but to be connected; not to be free, but to be human.", "آموخته‌ایم که بزرگ‌ترین چالش زندگی انسانی خوشحال بودن نیست، بلکه حاضر بودن است؛ موفق بودن نیست، بلکه وصل بودن؛ آزاد بودن نیست، بلکه انسان بودن."),
            StoryParagraph("And that, perhaps, is the deepest message of the novel: that to be human is to struggle, and that to struggle is to live, and that to live is to hope.", "و این، شاید، عمیق‌ترین پیام رمان است: انسان بودن یعنی مبارزه کردن و مبارزه کردن یعنی زندگی کردن و زندگی کردن یعنی امید داشتن."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the notes from the underground never truly end; they continue, in every generation, in every soul, in every person who has ever felt alone, and confused, and unable to live.", "زیرا یادداشت‌های زیرزمینی هرگز واقعاً تمام نمی‌شوند؛ در هر نسلی ادامه می‌یابند، در هر روحی، در هر کسی که هرگز حس کرده تنها است، گیج است، ناتوان از زندگی است."),
            StoryParagraph("And they will continue to be written, in different forms, in different times, by every underground man who has ever tried to make sense of his own existence.", "و به نوشته شدن ادامه می‌دهند، به اشکال مختلف، در زمان‌های مختلف، توسط هر مرد زیرزمینی که هرگز تلاش کرده به وجود خودش معنا بدهد.")
        )
    )
}